async function parsePdf(buffer){const isolated=Buffer.alloc(buffer.length);buffer.copy(isolated);try{return await require('pdf-parse')(new Uint8Array(isolated),{version:'v2.0.550'});}catch(error){throw new Error(`PDF parse failed: ${error.message}; details: ${error.details||''}`);}}
const members=[{userId:'assessor',name:'Synthetic assessor',organizationRole:'owner',teams:[],teamIds:[]},{userId:'employee',name:'Synthetic employee',organizationRole:'staff',departmentId:'delivery',teams:[{id:'team-a',role:'member'}],teamIds:['team-a']},{userId:'other',name:'Other employee',organizationRole:'staff',teams:[],teamIds:[]}];
const makeCtx=(who='admin',org='org-a')=>{const actor=who==='employee'?'employee':'assessor';const permissions=who==='staff'?[]:who==='editor'?['competency.assessment.view','competency.assessment.edit','competency.report.view','competency.evidence.view','competency.evidence.create']:who==='viewer'?['competency.assessment.view','competency.report.view','competency.evidence.view']:who==='employee'?['competency.assessment.view','competency.report.view','competency.evidence.view','competency.evidence.create']:auth.ACTIONS;return{organizationId:org,actor:{userId:actor,name:actor==='assessor'?'Synthetic assessor':'Synthetic employee'},user:{sub:actor,email:`${actor}@example.test`},permissions:new Set(permissions),organizationWide:who==='admin'||who==='editor'||who==='viewer',directory:{organizationId:org,canStartAppraisals:actor==='assessor',scope:who==='employee'?'self':'organization',organizationRole:who==='employee'?'staff':'owner',members,teams:[{id:'team-a'}],reviewers:[{userId:'assessor',name:'Synthetic assessor',organizationWide:true,eligibleTeamIds:[]}]}};};
const call=(method,url,who='admin',org='org-a')=>request(app)[method]('/api/competency'+url).set('x-who',who).set('x-org',org).set('Idempotency-Key',crypto.randomUUID());
async function configure(sources=['internal']){const ctx=makeCtx(),sourceRows=[];for(const source of sources){if(source==='strategy'){const s=await library.createStrategy(ctx,{title:'Strategy',description:'Synthetic strategy',criteria:[{id:'delivery',code:'DEL',name:'Delivery',description:'Delivery work',levelIds:[]}],levels:[]},{});sourceRows.push({...await library.publishStrategy(ctx,s.strategyId,s.id,s.revision),sourceType:'strategy'});}else{const f=await library.createFramework(ctx,{name:`${source} ${crypto.randomUUID()}`,sourceType:source,source:'Synthetic authored fixture',licenseProvenance:'Synthetic fixture only',levels:[{id:'low',label:'Guided',description:'Works with guidance',order:1},{id:'high',label:'Independent',description:'Works independently',order:2}],criteria:[{id:'delivery',code:'DEL',name:'Delivery',description:'Reliable delivery',levelIds:['low','high']}]});sourceRows.push(await library.publishFramework(ctx,f.id,f.draftVersion.id,1));}}
const role=await library.createRole(ctx,{name:`Delivery role ${crypto.randomUUID()}`,description:'Synthetic role',responsibilities:[{id:'r',text:'Deliver reliably'}],requirements:[{id:'q',text:'Experience',required:true}],criteria:sourceRows.map((source,index)=>({id:`criterion-${index}`,sourceType:source.sourceType,criterionId:'delivery',...(source.sourceType==='strategy'?{strategyVersionId:source.id,evaluationTarget:{scaleId:'percent',value:90}}:{frameworkVersionId:source.id,expectedLevelId:'high'}),weight:1,required:true,evidenceRequired:true,rationaleRequired:true,responsibilityIds:['r'],requirementIds:['q']}))});const publishedRole=await library.publishRole(ctx,role.id,role.draftVersion.id,1);const cycle=await library.createCycle(ctx,{name:'Synthetic cycle',period:{start:'2026-07-01',end:'2026-09-30'},selectedInputTypes:sources,frameworkVersionIds:sourceRows.filter(row=>row.sourceType!=='strategy').map(row=>row.id),strategyVersionIds:sourceRows.filter(row=>row.sourceType==='strategy').map(row=>row.id),roleVersionIds:[publishedRole.id],scoringConfig:{version:1,method:'weighted_mean',weightMode:'relative',inputWeights:Object.fromEntries(sources.map(s=>[s,1])),ratingScales:sources.includes('strategy')?[{id:'percent',label:'Completion',min:0,max:100}]:[],normalization:sourceRows.map(source=>({sourceVersionId:source.id,criterionId:'delivery',...(source.sourceType==='strategy'?{method:'rating_scale',ratingScaleId:'percent'}:{method:'level_map',levelScores:{low:60,high:80}})})),thresholds:[{id:'development',label:'Development needed',minInclusive:0,maxExclusive:75},{id:'suitable',label:'Suitable',minInclusive:75,maxInclusive:100}],missingPolicy:'block_unless_authorised_exception',exceptionPolicy:'retain_as_unscored'},rankingConfig:{enabled:true,scope:'role',direction:'desc',tieRule:'competition',decimalPlaces:2,measure:'overallScore'}});return{cycle:await library.publishCycle(ctx,cycle.id,1),role:publishedRole};}
async function launch(extra={}){return(await call('post','/assessments/launch').send({cycleId:fixture.cycle.id,cycleRevision:fixture.cycle.revision,assignments:[{participantId:'employee',roleVersionId:fixture.role.id,assessorIds:['assessor'],...extra}]}).expect(201)).body.data.outcomes[0].assessmentId;}
async function fill(assessmentId,{visibility='participant'}={}){const detail=(await call('get',`/assessments/${assessmentId}`).expect(200)).body.data;const evidence=(await call('post',`/assessments/${assessmentId}/evidence`).send({title:'Synthetic delivery evidence',text:'Completed work on schedule.',criterionIds:detail.definitionSnapshot.criteria.map(c=>c.id),visibility}).expect(201)).body.data;const current=(await call('get',`/assessments/${assessmentId}`).expect(200)).body.data;const items=current.definitionSnapshot.criteria.map(c=>({criterionId:c.id,status:'assessed',...(c.sourceType==='strategy'?{rating:80}:{observedLevelId:'high'}),rationale:'Observed in synthetic evidence.',evidenceIds:[evidence.id],reviewedSuggestionIds:[]}));return(await call('patch',`/assessments/${assessmentId}`).set('If-Match',String(current.revision)).send({items,managerFeedback:[{id:'overall-note',section:'overall',text:'Manager overall sentinel',submitted:true}]}).expect(200)).body.data;}
beforeAll(async()=>{mongo=await MongoMemoryReplSet.create({replSet:{count:1}});await mongoose.connect(mongo.getUri());app=express();app.use(express.json());app.use((req,res,next)=>{if(req.get('x-who')!=='anonymous'){const ctx=makeCtx(req.get('x-who'),req.get('x-org'));ctx.req=req;req.competencyContext=ctx;req.session={currentOrganizationId:ctx.organizationId,user:{...ctx.user,id:ctx.actor.userId,name:ctx.actor.name,organizations:[{id:ctx.organizationId,role:ctx.organizationWide?'owner':'employee'}]}};req._performanceDirectory=ctx.directory;}next();});app.use('/api/competency',require('../routes/competency/assessments'));});
beforeEach(async()=>{await mongoose.connection.db.dropDatabase();for(const model of [Assessment,Operation,require('../models/CompetencyEvidence'),require('../models/CompetencyAISuggestion'),require('../models/CompetencyRole'),require('../models/CompetencyRoleVersion'),require('../models/CompetencyFramework'),require('../models/CompetencyFrameworkVersion'),require('../models/CompetencyStrategyVersion'),require('../models/CompetencyCycle'),require('../services/competency/retentionService').Lease,require('../services/competency/reportService').Export])await model.createIndexes();fixture=await configure();jest.spyOn(auth,'refreshContext').mockImplementation(async req=>req.competencyContext);});afterEach(()=>jest.restoreAllMocks());afterAll(async()=>{await mongoose.disconnect();await mongo.stop();});
test('CA-008 launch real definition/role snapshot, same-key replay and cross-org no access',async()=>{const key=crypto.randomUUID(),input={cycleId:fixture.cycle.id,cycleRevision:fixture.cycle.revision,assignments:[{participantId:'employee',roleVersionId:fixture.role.id,assessorIds:['assessor']}]};const first=(await call('post','/assessments/launch').set('Idempotency-Key',key).send(input).expect(201)).body.data;expect((await call('post','/assessments/launch').set('Idempotency-Key',key).send(input).expect(201)).body.data).toEqual(first);expect(await Assessment.countDocuments()).toBe(1);const id=first.outcomes[0].assessmentId;await call('get',`/assessments/${id}`,'admin','org-b').expect(404);await call('get',`/assessments/${id}`,'staff').expect(403);await call('get',`/assessments/${id}`,'anonymous').expect(401);await call('post','/assessments/launch').set('Idempotency-Key',key).send({...input,assignments:[{...input.assignments[0],participantId:'other'}]}).expect(409);});
