test('CA-109 editor cannot finalise; viewer cannot edit or export despite report-view grant',async()=>{const id=await launch(),filled=await fill(id);await call('post',`/assessments/${id}/finalise`,'editor').set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(403);await call('patch',`/assessments/${id}`,'viewer').set('If-Match',String(filled.revision)).send({items:[]}).expect(403);await call('post',`/assessments/${id}/exports`,'viewer').send({}).expect(403);});
test('CA-101/102 manual evidence/oral remain usable without scanner AI or calls, private evidence filtered for employee',async()=>{const id=await launch(),filled=await fill(id,{visibility:'assessors'});const oral=(await call('post',`/assessments/${id}/oral-sessions`).send({title:'Synthetic manual discussion',prompts:[{criterionId:'criterion-0',question:'How was it delivered?',answer:'On schedule.',notes:'Observed clarity.'}],visibility:'assessors'}).expect(201)).body.data;expect(oral.callType).toBe('manual');const employee=(await call('get',`/assessments/${id}`,'employee').expect(200)).body.data;expect(employee.evidence).toEqual([]);expect(employee.items).toEqual([]);expect(employee.oralSessions).toEqual([]);expect(employee.aiSuggestions).toEqual([]);await call('get',`/assessments/${id}/evidence/${filled.evidence[0].id}`,'employee').expect(404);await call('patch',`/assessments/${id}/oral-sessions/${oral.id}`).set('If-Match','0').send({title:'stale'}).expect(409);});
test('CA-110 completion blocks required evidence; reasoned exception produces unscored result',async()=>{const id=await launch();const check=(await call('post',`/assessments/${id}/completion-check`).send({}).expect(200)).body.data;expect(check.ready).toBe(false);await call('post',`/assessments/${id}/finalise`).set('If-Match','1').send({classificationId:'development',reason:'Insufficient retained evidence.'}).expect(422);const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match','1').send({classificationId:'development',reason:'Human classification with missing evidence.',exceptions:[{criterionId:'criterion-0',reason:'Authorised synthetic exception.'}]}).expect(200)).body.data;expect(pub.status).toBe('published');expect(pub.result.score.overallScore).toBeNull();expect(pub.result.exceptions[0].author.userId).toBe('assessor');});
test('CA-112/114 atomic published snapshot/reopen new revision preserves old hashes and report source versions',async()=>{const id=await launch(),filled=await fill(id);const key=crypto.randomUUID(),body={classificationId:'suitable'};const published=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).set('Idempotency-Key',key).send(body).expect(200)).body.data;expect(published.status).toBe('published');expect(published.result.score.overallScore).toBe(80);expect((await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).set('Idempotency-Key',key).send(body).expect(200)).body.data).toEqual(published);const old=(await call('get',`/assessments/${id}/report`).expect(200)).body.data;await call('patch',`/assessments/${id}`).set('If-Match',String(published.revision)).send({items:[]}).expect(409);const reopened=(await call('post',`/assessments/${id}/reopen`).set('If-Match',String(published.revision)).send({reason:'Add new synthetic evidence.'}).expect(200)).body.data;expect(reopened.status).toBe('reopened');const second=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(reopened.revision)).send(body).expect(200)).body.data;expect(second.result.number).toBe(2);const historical=(await call('get',`/assessments/${id}/report?resultVersion=1`).expect(200)).body.data;expect(historical.reportHash).toBe(old.reportHash);expect(historical.visibilityHash).toBe(old.visibilityHash);expect(historical.status).toBe('superseded');});
test('CA-112 PDF private export generated from filtered frozen DTO and denied across tenant/action',async()=>{const id=await launch(),filled=await fill(id);await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(200);const job=(await call('post',`/assessments/${id}/exports`).send({resultVersion:1}).expect(201)).body.data;expect(job.status).toBe('ready');const downloaded=await call('get',`/exports/${job.id}/download`).expect(200);expect(downloaded.headers['content-type']).toMatch(/pdf/);expect(downloaded.headers['content-disposition']).toMatch(/attachment/);expect(downloaded.body.slice(0,4).toString()).toBe('%PDF');await call('get',`/exports/${job.id}/download`,'admin','org-b').expect(404);await call('get',`/exports/${job.id}/download`,'viewer').expect(403);const source=await require('../services/competency/reportService').Export.findById(job.id).select('+storageKey');await require('../services/competency/fileSafetyService').deletePrivate(source.storageKey);});
test.each([['sfia'],['internal'],['strategy'],['sfia','internal'],['sfia','strategy'],['internal','strategy'],['sfia','internal','strategy']])('CA-004/106/112 persisted launch assess publish report for %j',async(...args)=>{fixture=await configure(args.filter(value=>typeof value==='string'));const id=await launch(),filled=await fill(id);const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(200)).body.data;expect(pub.result.score.overallScore).toBe(80);expect(pub.result.selectedSources).toEqual(args.filter(value=>typeof value==='string'));const calculated=(await call('post',`/assessments/${id}/calculate`).send({}).expect(200)).body.data;expect(calculated.score.overallScore).toBe(80);const job=(await call('post',`/assessments/${id}/exports`).send({resultVersion:1}).expect(201)).body.data;const pdf=await call('get',`/exports/${job.id}/download`).expect(200);const parsed=await parsePdf(pdf.body);expect(parsed.text).toContain(pub.result.selectedSources.join(', '));expect(parsed.text).toContain('80 / 100');expect(parsed.text).toContain('version 1');if(pub.result.selectedSources.some(source=>source!=='strategy'))expect(parsed.text).toContain('Works independently');const exportDoc=await require('../services/competency/reportService').Export.findById(job.id).select('+storageKey');await require('../services/competency/fileSafetyService').deletePrivate(exportDoc.storageKey);});
test('CA-111 linked reviewer required, actual actor and all comments frozen; later amendment warns without changing old report',async()=>{const cycleId=new mongoose.Types.ObjectId();const appraisal=await Appraisal.create({cycleId,organizationId:'org-a',employee:{userId:'employee',name:'Synthetic employee',email:'employee@example.test'},manager:{userId:'assessor',name:'Synthetic assessor',email:'assessor@example.test'},cycleConfigurationSnapshot:{appraisalFlow:{steps:[{id:'reviewer',type:'managerReview'}]},workflowDefinition:{sections:[{id:'custom',title:'Frozen section sentinel',questions:[{id:'question',prompt:'Frozen question prompt sentinel',responseType:'long_text'}]}]}}});const id=await launch({appraisalId:String(appraisal._id)}),filled=await fill(id);await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(422);await Appraisal.updateOne({_id:appraisal._id},{$set:{managerReview:{submittedAt:new Date(),overallManagerRating:4,overallSummary:{achievements:'Overall sentinel',strengths:'Strength sentinel',improvements:'Improvement sentinel',recommendations:'Recommend sentinel'},competencyRatings:[{competencyId:'competency',competencyName:'Delivery',managerRating:4,managerComments:'Competency sentinel'}],okrAssessment:[{okrId:new mongoose.Types.ObjectId(),okrTitle:'Goal',managerComments:'Goal sentinel',qualityRating:4}]},customResponses:[{sectionId:'custom',questionId:'question',respondentRole:'manager',respondentId:'assessor',value:'Custom sentinel',submittedAt:new Date()}],auditLog:[{action:'manager_review_submitted',performedBy:{userId:'assessor',name:'Actual submitting reviewer'},timestamp:new Date()}]}});const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(200)).body.data;expect(pub.result.managerFeedback.map(value=>value.text).join(' ')).toContain('Goal sentinel');expect(pub.result.managerFeedback.map(value=>value.text).join(' ')).toContain('Custom sentinel');expect(pub.result.managerFeedback.find(value=>value.section==='custom').questionPrompt).toBe('Frozen question prompt sentinel');expect(pub.result.managerFeedback.find(value=>value.section==='custom').sectionTitle).toBe('Frozen section sentinel');expect(pub.result.managerSource.author.name).toBe('Actual submitting reviewer');expect(pub.result.managerSource.overallManagerRating).toBe(4);await Appraisal.updateOne({_id:appraisal._id},{$set:{'managerReview.okrAssessment.0.managerComments':'Amended goal'}});const detail=(await call('get',`/assessments/${id}`).expect(200)).body.data;expect(detail.sourceFeedbackChanged).toBe(true);const report=(await call('get',`/assessments/${id}/report`).expect(200)).body.data;expect(report.reportHash).toBe(pub.result.reportHash);expect(report.managerFeedback.map(value=>value.text).join(' ')).not.toContain('Amended goal');});
