test('CA-104 evidence withdrawn while AI runs cancels pending draft publication (explicit mock provider)',async()=>{const id=await launch(),filled=await fill(id),settings=await require('../services/competency/settingsService').updateSettings(makeCtx(),{aiDraftsEnabled:true,evidenceRetentionDays:30,noticeText:'Synthetic notice.'},0),evidenceId=filled.evidence[0].id;const Evidence=require('../models/CompetencyEvidence');jest.spyOn(require('../services/sharedAIAccountService'),'complete').mockImplementation(async()=>{await Evidence.updateOne({_id:evidenceId},{$set:{status:'deleted',text:'',spans:[]}});return{content:JSON.stringify({observations:[{criterionId:'criterion-0',text:'On-time work',citations:[{evidenceId,spanId:'span-1',quote:'Completed work on schedule.'}]}]})};});await call('post',`/assessments/${id}/ai-suggestions`).send({evidenceIds:[evidenceId],consent:{acknowledged:true,policyVersion:settings.policyVersion}}).expect(409);expect(await require('../models/CompetencyAISuggestion').countDocuments({status:'ready'})).toBe(0);});
test('CA-103 call link checks participant consent, source ownership and native type; raw transcript never frozen (synthetic persisted call)',async()=>{const id=await launch();const settings=await require('../services/competency/settingsService').updateSettings(makeCtx(),{callEvidenceEnabled:true,mediaRetentionDays:30,noticeText:'Synthetic recording and transcription notice.'},0);const meeting=await require('../models/OneOnOne').create({organizationId:'org-a',managerId:'assessor',employeeId:'employee',title:'Synthetic completed native call',scheduledDate:new Date(),status:'completed',appraisalMeeting:{mode:'in_app',recordingConsent:{noticeVersion:'appraisal-recording-v1',manager:{userId:'assessor',acceptedAt:new Date()},employee:{userId:'employee',acceptedAt:new Date()}}},transcript:{status:'ready',content:'Synthetic confidential transcript.'}});const body={title:'Linked oral session',status:'submitted',prompts:[{criterionId:'criterion-0',question:'Explain delivery',answer:'On schedule',notes:'Good clarity'}],callType:'native',callId:String(meeting._id),visibility:'participant',consent:{recording:true,transcription:true,policyVersion:settings.noticeVersion}};await call('post',`/assessments/${id}/call-consents/${meeting._id}`).send({acknowledged:true,recording:true,transcription:true,assessmentUse:true,policyVersion:settings.noticeVersion}).expect(200);await call('post',`/assessments/${id}/call-consents/${meeting._id}`,'employee').send({acknowledged:true,recording:true,transcription:true,assessmentUse:true,policyVersion:settings.noticeVersion}).expect(200);const linked=(await call('post',`/assessments/${id}/oral-sessions`).send(body).expect(201)).body.data;expect(linked.source.text).toBeUndefined();expect((await call('get',`/assessments/${id}/oral-sessions/${linked.id}/transcript`).expect(200)).body.data.text).toBe('Synthetic confidential transcript.');await call('post',`/assessments/${id}/oral-sessions`).send({...body,callType:'nylas'}).expect(422);const filled=await fill(id);const published=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(200)).body.data;expect(JSON.stringify(published.result)).not.toContain('Synthetic confidential transcript.');await require('../models/OneOnOne').updateOne({_id:meeting._id},{$set:{'appraisalMeeting.recordingConsent.revokedAt':new Date()}});await call('get',`/assessments/${id}/oral-sessions/${linked.id}/transcript`).expect(409);await call('post',`/assessments/${id}/oral-sessions`).send(body).expect(409);});
test('CA-103 legacy calendar call without actual participant consent cannot be legitimized by assessor checkbox',async()=>{const id=await launch(),settings=await require('../services/competency/settingsService').updateSettings(makeCtx(),{callEvidenceEnabled:true,mediaRetentionDays:30,noticeText:'Synthetic recording notice.'},0);const meeting=await require('../models/OneOnOne').create({organizationId:'org-a',managerId:'assessor',employeeId:'employee',scheduledDate:new Date(),status:'completed',appraisalMeeting:{mode:'calendar',recordingRequested:true},transcript:{status:'ready',content:'Synthetic'}});await call('post',`/assessments/${id}/oral-sessions`).send({title:'Legacy call',prompts:[{criterionId:'criterion-0',question:'Delivery?'}],callType:'nylas',callId:String(meeting._id),consent:{recording:true,transcription:true,policyVersion:settings.noticeVersion}}).expect(409);});
test('CA-115 deletion tombstone preserves result hash; current availability reflects withdrawal',async()=>{const id=await launch(),filled=await fill(id);const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(200)).body.data;await call('delete',`/assessments/${id}/evidence/${filled.evidence[0].id}`).expect(200);const report=(await call('get',`/assessments/${id}/report`).expect(200)).body.data;expect(report.reportHash).toBe(pub.result.reportHash);expect(report.sourceAvailability[0].status).toBe('deleted');const evidence=await require('../models/CompetencyEvidence').findById(filled.evidence[0].id);expect(evidence.text).toBe('');expect(evidence.spans).toHaveLength(0);});
test('CA-115 legal holds block deletion/expiry; due private exports delete bytes before tombstones',async()=>{const id=await launch(),filled=await fill(id),Evidence=require('../models/CompetencyEvidence'),retention=require('../services/competency/retentionService');await Evidence.updateOne({_id:filled.evidence[0].id},{$set:{legalHold:true,'retention.expiresAt':new Date(0)}});await call('delete',`/assessments/${id}/evidence/${filled.evidence[0].id}`).expect(409);let stats=await retention.processDue({now:new Date()});expect(stats.evidenceDeleted).toBe(0);await Evidence.updateOne({_id:filled.evidence[0].id},{$set:{legalHold:false}});stats=await retention.processDue({now:new Date()});expect(stats.evidenceDeleted).toBe(1);const status=await Evidence.findById(filled.evidence[0].id);expect(status.status).toBe('deleted');});
test('CA-115 storage failure keeps retryable deletion state and never false-completes',async()=>{const id=await launch(),filled=await fill(id),Evidence=require('../models/CompetencyEvidence');await Evidence.updateOne({_id:filled.evidence[0].id},{$set:{storageKey:crypto.randomUUID()}});jest.spyOn(require('../services/competency/fileSafetyService'),'deletePrivate').mockRejectedValue(new Error('Synthetic storage denial'));await call('delete',`/assessments/${id}/evidence/${filled.evidence[0].id}`).expect(503);expect((await Evidence.findById(filled.evidence[0].id)).status).toBe('deletion_failed');});
test('CA-110 failed atomic publication leaves draft and no immutable result',async()=>{const id=await launch(),filled=await fill(id),original=Assessment.findOneAndUpdate.bind(Assessment);jest.spyOn(Assessment,'findOneAndUpdate').mockImplementation((filter,update,options)=>{if(update.$set?.status==='published')return{lean:()=>Promise.reject(new Error('Synthetic persistence failure'))};return original(filter,update,options);});await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(500);const current=await Assessment.findById(id).lean();expect(current.status).toBe('in_progress');expect(current.results).toHaveLength(0);});
test('CA-111 disabled reviewer has explicit report label and no invented empty submission',async()=>{const appraisal=await Appraisal.create({cycleId:new mongoose.Types.ObjectId(),organizationId:'org-a',employee:{userId:'employee',name:'Employee',email:'employee@example.test'},manager:{userId:'assessor',name:'Assessor',email:'assessor@example.test'},cycleConfigurationSnapshot:{appraisalFlow:{steps:[{id:'final',type:'finalReview'}]}}});const id=await launch({appraisalId:String(appraisal._id)}),filled=await fill(id);const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(200)).body.data;expect(pub.result.managerSource.state).toBe('not_configured');expect(pub.result.managerSource.label).toBe('Reviewer step not configured');expect(pub.result.managerSource.author).toBeNull();});
test('CA-111 unchanged feedback preserves actual other author and submission timestamp; tampering denied',async()=>{const id=await launch(),filled=await fill(id);const recorded={id:'other-author-note',section:'recommendation',criterionId:null,goalId:null,text:'Recommendation from another assessor',submitted:true,author:{userId:'another-assessor',name:'Other actual assessor'},submittedAt:'2026-10-18T10:00:00.000Z'};await Assessment.updateOne({_id:id},{$push:{managerFeedback:recorded}});const saved=await Assessment.findById(id).lean();const feedback=saved.managerFeedback.map(({id,section,criterionId,goalId,text,submitted})=>({id,section,criterionId,goalId,text,submitted}));feedback.push({id:'new-own-note',section:'overall',text:'Another own observation',submitted:true});const result=(await call('patch',`/assessments/${id}`).set('If-Match',String(saved.revision)).send({managerFeedback:feedback}).expect(200)).body.data;expect(result.managerFeedback.find(note=>note.id===recorded.id)).toEqual(recorded);feedback.find(note=>note.id===recorded.id).text='Forged amendment';await call('patch',`/assessments/${id}`).set('If-Match',String(result.revision)).send({managerFeedback:feedback}).expect(403);});
test('CA-008 different role in same cycle conflicts; a linked appraisal cannot get a second assessment',async()=>{const ctx=makeCtx();const secondRole=await library.createRole(ctx,{name:'Second assessment role',description:'Synthetic second role',responsibilities:[{id:'r',text:'Deliver reliably'}],requirements:[{id:'q',text:'Experience',required:true}],criteria:fixture.role.criteria});const pubRole=await library.publishRole(ctx,secondRole.id,secondRole.draftVersion.id,1);const oldCycle=await require('../models/CompetencyCycle').findById(fixture.cycle.id).lean();const body=Object.fromEntries(['name','period','selectedInputTypes','frameworkVersionIds','strategyVersionIds','scoringConfig','rankingConfig'].map(key=>[key,oldCycle[key]]));body.roleVersionIds=[fixture.role.id,pubRole.id];const cycle=await library.createCycle(ctx,body);fixture.cycle=await library.publishCycle(ctx,cycle.id,1);const id=await launch();await call('post','/assessments/launch').send({cycleId:fixture.cycle.id,cycleRevision:fixture.cycle.revision,assignments:[{participantId:'employee',roleVersionId:pubRole.id,assessorIds:['assessor']}]}).expect(409);expect(await Assessment.countDocuments({cycleId:fixture.cycle.id})).toBe(1);const saved=await Assessment.findById(id).lean();const sharedAppraisalId=String(new mongoose.Types.ObjectId());await Assessment.updateOne({_id:id},{$set:{appraisalId:sharedAppraisalId}});delete saved._id;await expect(Assessment.create({...saved,cycleId:String(new mongoose.Types.ObjectId()),appraisalId:sharedAppraisalId,participant:{userId:'other',name:'Other'}})).rejects.toMatchObject({code:11000});});
test('CA-115 expiry removes real private PDF bytes before retaining job tombstone; expired lease is reclaimable',async()=>{const id=await launch(),filled=await fill(id);await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(200);const job=(await call('post',`/assessments/${id}/exports`).send({}).expect(201)).body.data;const exports=require('../services/competency/reportService').Export;const source=await exports.findById(job.id).select('+storageKey');await exports.updateOne({_id:job.id},{$set:{expiresAt:new Date(0)}});const stat=await require('../services/competency/retentionService').processDue({now:new Date()});expect(stat.exportsDeleted).toBe(1);expect((await exports.findById(job.id)).status).toBe('expired');await expect(require('../services/competency/fileSafetyService').readPrivate(source.storageKey)).rejects.toMatchObject({status:404});await call('get',`/exports/${job.id}/download`).expect(410);});
test('CA-110 human override reason required and exception privilege separate from editing',async()=>{const id=await launch(),filled=await fill(id);await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'development'}).expect(422);await call('post',`/assessments/${id}/completion-check`,'editor').send({exceptions:[{criterionId:'criterion-0',reason:'Attempt without exception grant'}]}).expect(403);const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'development',reason:'Human judgement based on contextual evidence.'}).expect(200)).body.data;expect(pub.result.suggestedOutcome.id).toBe('suitable');expect(pub.result.finalClassification.id).toBe('development');expect(pub.result.finalClassification.finalisedBy.userId).toBe('assessor');});
test('CA-110 linked transaction audit failure rolls back source guard and publication atomically',async()=>{const appraisal=await Appraisal.create({cycleId:new mongoose.Types.ObjectId(),organizationId:'org-a',employee:{userId:'employee',name:'Employee',email:'employee@example.test'},manager:{userId:'assessor',name:'Assessor',email:'assessor@example.test'},cycleConfigurationSnapshot:{appraisalFlow:{steps:[{id:'final',type:'finalReview'}]}}});const id=await launch({appraisalId:String(appraisal._id)}),filled=await fill(id),beforeVersion=(await Appraisal.findById(appraisal._id)).__v,Audit=require('../models/CompetencyAuditEvent'),original=Audit.create.bind(Audit);jest.spyOn(Audit,'create').mockImplementation((documents,options)=>Array.isArray(documents)&&documents[0]?.action==='assessment.published'?Promise.reject(new Error('Synthetic audit transaction failure')):original(documents,options));await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(500);const after=await Assessment.findById(id);expect(after.status).toBe('in_progress');expect(after.results).toHaveLength(0);expect((await Appraisal.findById(appraisal._id)).__v).toBe(beforeVersion);});
