test('CA-115 crashed mutation lease recovers without losing draft or published provenance',async()=>{const id=await launch();await Assessment.updateOne({_id:id},{$set:{mutationLock:'synthetic-crashed-process',mutationLeaseUntil:new Date(0)}});const result=await require('../services/competency/retentionService').processDue({now:new Date()});const record=await Assessment.findById(id).lean();expect(record.mutationLock).toBeNull();expect(record.revision).toBe(2);await call('patch',`/assessments/${id}`).set('If-Match','2').send({items:[]}).expect(200);});
test('CA-102 manual oral date/timezone draft/resume required answers, amendment history and single qualifying evidence',async()=>{const id=await launch(),body={title:'Structured manual oral assessment',occurredAt:'2026-10-18T14:00:00.000Z',timeZone:'Europe/London',participants:['employee','assessor'],status:'draft',visibility:'participant',prompts:[{criterionId:'criterion-0',question:'Explain how delivery was completed',answer:'',notes:'Assessor private draft sentinel',required:true}]};let oral=(await call('post',`/assessments/${id}/oral-sessions`).send(body).expect(201)).body.data;expect(oral.status).toBe('draft');expect(oral.timeZone).toBe('Europe/London');expect(oral.occurredAt).toBe(body.occurredAt);await call('patch',`/assessments/${id}/oral-sessions/${oral.id}`).set('If-Match',String(oral.revision)).send({status:'submitted'}).expect(422);const participant=(await call('get',`/assessments/${id}`,'employee').expect(200)).body.data;expect(JSON.stringify(participant)).not.toContain('Assessor private draft sentinel');expect(participant.items).toEqual([]);await call('get',`/assessments/${id}/evidence/${oral.evidenceId}`,'employee').expect(404);oral=(await call('patch',`/assessments/${id}/oral-sessions/${oral.id}`).set('If-Match',String(oral.revision)).send({status:'submitted',prompts:[{...body.prompts[0],answer:'I completed delivery on schedule.',notes:'Assessor submitted observation'}]}).expect(200)).body.data;expect(oral.status).toBe('submitted');expect(oral.submittedAt).toBeTruthy();expect(oral.versions).toHaveLength(1);expect(oral.versions[0].prompts[0].answer).toBe('');const detail=(await call('get',`/assessments/${id}`).expect(200)).body.data;expect(detail.evidence.filter(source=>source.kind==='oral')).toHaveLength(1);const saved=(await call('patch',`/assessments/${id}`).set('If-Match',String(detail.revision)).send({items:[{criterionId:'criterion-0',status:'assessed',observedLevelId:'high',rationale:'Based on structured oral response',evidenceIds:[oral.evidenceId],reviewedSuggestionIds:[]}]}).expect(200)).body.data;const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(saved.revision)).send({classificationId:'suitable'}).expect(200)).body.data;expect(pub.result.oralFindings).toHaveLength(1);expect(pub.result.oralFindings[0].participants).toHaveLength(2);expect(pub.result.score.coverage.assessedRequired).toBe(1);await call('post',`/assessments/${id}/reopen`).set('If-Match',String(pub.revision)).send({reason:'Add private draft sentinel'}).expect(200);const changed=await Assessment.findById(id);changed.items[0].rationale='Reopened private draft sentinel';changed.markModified('items');await changed.save();const employee=(await call('get',`/assessments/${id}`,'employee').expect(200)).body.data;expect(JSON.stringify(employee)).not.toContain('Reopened private draft sentinel');expect(employee.result.reportHash).toBe(pub.result.reportHash);});
test('CA-113 scoped cohort completion states and private PDF use the same captured aggregate',async()=>{const id=await launch();let cohort=(await call('get',`/cycles/${fixture.cycle.id}/report`).expect(200)).body.data;expect(cohort.completionCounts.not_started).toBe(1);await fill(id);cohort=(await call('get',`/cycles/${fixture.cycle.id}/report`).expect(200)).body.data;expect(cohort.completionCounts.ready).toBe(1);const job=(await call('post',`/cycles/${fixture.cycle.id}/exports`).send({filters:{departmentId:'delivery'}}).expect(201)).body.data;expect(job.kind).toBe('cohort');expect(job.status).toBe('ready');const pdf=await call('get',`/exports/${job.id}/download`).expect(200);expect(pdf.body.slice(0,4).toString()).toBe('%PDF');await call('post',`/cycles/${fixture.cycle.id}/exports`,'viewer').send({filters:{}}).expect(403);await call('get',`/exports/${job.id}/download`,'admin','org-b').expect(404);const Export=require('../services/competency/reportService').Export,saved=await Export.findById(job.id).select('+storageKey');await require('../services/competency/fileSafetyService').deletePrivate(saved.storageKey);});
test('CA-115 legacy raw transcript fields are stripped from immutable result/report and cannot be replayed in PDF',async()=>{const id=await launch(),filled=await fill(id);await require('../models/CompetencyOralSession').create({organizationId:'org-a',assessmentId:id,participantId:'employee',title:'Legacy synthetic manual source',callType:'manual',status:'submitted',prompts:[{criterionId:'criterion-0',question:'How was delivery?',answer:'On schedule.',notes:'Human observation'}],source:{type:'meeting_transcript',sha256:'synthetic',text:'RAW_TRANSCRIPT_SENTINEL_NEVER_FREEZE',providerUrl:'https://example.test/private-provider'},visibility:'participant'});const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(200)).body.data;expect(JSON.stringify(pub.result)).not.toContain('RAW_TRANSCRIPT_SENTINEL_NEVER_FREEZE');expect(JSON.stringify(pub.result)).not.toContain('private-provider');expect(JSON.stringify((await Assessment.findById(id)).results)).not.toContain('RAW_TRANSCRIPT_SENTINEL_NEVER_FREEZE');});
test('CA-101/102 create retries are idempotent and deletion cannot be undone through cached receipts',async()=>{const id=await launch(),key=crypto.randomUUID(),input={title:'Synthetic retriable evidence',text:'Source text must not be resurrected',criterionIds:['criterion-0'],visibility:'participant'};const first=(await call('post',`/assessments/${id}/evidence`).set('Idempotency-Key',key).send(input).expect(201)).body.data;expect((await call('post',`/assessments/${id}/evidence`).set('Idempotency-Key',key).send(input).expect(201)).body.data.id).toBe(first.id);expect(await require('../models/CompetencyEvidence').countDocuments({assessmentId:id})).toBe(1);await call('post',`/assessments/${id}/evidence`).set('Idempotency-Key',key).send({...input,text:'Changed input'}).expect(409);await call('delete',`/assessments/${id}/evidence/${first.id}`).expect(200);const retried=(await call('post',`/assessments/${id}/evidence`).set('Idempotency-Key',key).send(input).expect(201)).body.data;expect(retried.status).toBe('deleted');expect(JSON.stringify(retried)).not.toContain(input.text);const oralKey=crypto.randomUUID(),oralBody={title:'Retriable oral draft',prompts:[{criterionId:'criterion-0',question:'Explain delivery',answer:'Synthetic answer'}],status:'submitted'};const oral=(await call('post',`/assessments/${id}/oral-sessions`).set('Idempotency-Key',oralKey).send(oralBody).expect(201)).body.data;const retry=(await call('post',`/assessments/${id}/oral-sessions`).set('Idempotency-Key',oralKey).send(oralBody).expect(201)).body.data;expect(retry.id).toBe(oral.id);expect(await require('../models/CompetencyOralSession').countDocuments({assessmentId:id})).toBe(1);});
test('CA-116 ten synthetic participants complete internal-only manual assessments, comparable ties and scoped cohort/PDF without integrations',async()=>{const original=members.map(member=>JSON.parse(JSON.stringify(member)));try{for(let index=0;index<8;index++)members.push({userId:`pilot-${index+1}`,name:`Synthetic pilot ${index+1}`,organizationRole:'staff',departmentId:'delivery',teams:[{id:'team-a',role:'member'}],teamIds:['team-a']});const people=members.filter(member=>member.userId!=='assessor');people.forEach(person=>{person.departmentId='delivery';person.teamIds=['team-a'];});const launched=(await call('post','/assessments/launch').send({cycleId:fixture.cycle.id,cycleRevision:fixture.cycle.revision,assignments:people.map(person=>({participantId:person.userId,roleVersionId:fixture.role.id,assessorIds:['assessor']}))}).expect(201)).body.data;expect(launched.outcomes).toHaveLength(10);const settings=await require('../services/competency/settingsService').getSettings('org-a');expect(settings.aiDraftsEnabled).toBe(false);expect(settings.callEvidenceEnabled).toBe(false);for(const [index,outcome]of launched.outcomes.entries()){const assessmentId=outcome.assessmentId;const oral=(await call('post',`/assessments/${assessmentId}/oral-sessions`).send({title:`Manual pilot discussion ${index+1}`,status:'submitted',occurredAt:'2026-10-18T14:00:00.000Z',timeZone:'Europe/London',visibility:'participant',prompts:[{criterionId:'criterion-0',question:'Describe delivery evidence',answer:`Synthetic participant ${index+1} describes completed work.`,notes:'Human assessor observed the evidence.',required:true}]}).expect(201)).body.data;const detail=(await call('get',`/assessments/${assessmentId}`).expect(200)).body.data;const saved=(await call('patch',`/assessments/${assessmentId}`).set('If-Match',String(detail.revision)).send({items:[{criterionId:'criterion-0',status:'assessed',observedLevelId:index<2?'high':'low',rationale:'Based on submitted manual oral evidence.',evidenceIds:[oral.evidenceId],reviewedSuggestionIds:[]}]}).expect(200)).body.data;const calculation=(await call('post',`/assessments/${assessmentId}/calculate`).send({}).expect(200)).body.data;expect(calculation.score.overallScore).toBe(index<2?80:60);const published=(await call('post',`/assessments/${assessmentId}/finalise`).set('If-Match',String(saved.revision)).send({classificationId:index<2?'suitable':'development'}).expect(200)).body.data;expect(published.result.oralFindings).toHaveLength(1);expect(published.result.selectedSources).toEqual(['internal']);}const cohort=(await call('get',`/cycles/${fixture.cycle.id}/report`).expect(200)).body.data;expect(cohort.total).toBe(10);expect(cohort.completed).toBe(10);expect(cohort.completionCounts.finalised).toBe(10);expect(cohort.rankings.map(row=>row.rank).sort((a,b)=>a-b)).toEqual([1,1,3,3,3,3,3,3,3,3]);const ctx=makeCtx();ctx.organizationWide=false;ctx.directory.scope='managed_teams';ctx.directory.members=members.filter(person=>['assessor',people[0].userId,people[1].userId].includes(person.userId));const scoped=await require('../services/competency/reportService').cohort(ctx,fixture.cycle.id);expect(scoped.total).toBe(2);expect(scoped.completed).toBe(2);expect(JSON.stringify(scoped)).not.toContain('Synthetic pilot 8');const job=(await call('post',`/cycles/${fixture.cycle.id}/exports`).send({filters:{}}).expect(201)).body.data;const pdf=await call('get',`/exports/${job.id}/download`).expect(200),parsed=await parsePdf(pdf.body);expect(parsed.text).toContain('10 authorised assessments; 10 finalised');expect(parsed.text).toContain('Synthetic pilot 8');const record=await require('../services/competency/reportService').Export.findById(job.id).select('+storageKey');await require('../services/competency/fileSafetyService').deletePrivate(record.storageKey);}finally{members.splice(0,members.length,...original);}});
test('CA-115 expired ready source is unavailable before cleanup: read, download, AI, completion and finalisation',async()=>{const id=await launch(),filled=await fill(id),Evidence=require('../models/CompetencyEvidence'),files=require('../services/competency/fileSafetyService');const storageKey=await files.storePrivate(Buffer.from('Synthetic expired private file'));await Evidence.updateOne({_id:filled.evidence[0].id},{$set:{storageKey,kind:'file',originalName:'synthetic.txt',mimeType:'text/plain',scanner:{provider:'EXPLICIT TEST scanner fixture',scannedAt:new Date()},'retention.expiresAt':new Date(0)}});const source=(await call('get',`/assessments/${id}/evidence/${filled.evidence[0].id}`).expect(200)).body.data;expect(source.status).toBe('expired');expect(source.text).toBeUndefined();await call('get',`/assessments/${id}/evidence/${filled.evidence[0].id}/source`).expect(409);expect((await files.readPrivate(storageKey)).toString()).toBe('Synthetic expired private file');const calculated=(await call('post',`/assessments/${id}/calculate`).send({}).expect(200)).body.data;expect(calculated.score.overallScore).toBeNull();expect(calculated.completion.ready).toBe(false);await call('post',`/assessments/${id}/finalise`).set('If-Match',String(filled.revision)).send({classificationId:'suitable'}).expect(422);const settings=await require('../services/competency/settingsService').updateSettings(makeCtx(),{aiDraftsEnabled:true,evidenceRetentionDays:30,noticeText:'Synthetic AI notice.'},0),provider=jest.spyOn(require('../services/sharedAIAccountService'),'complete');await call('post',`/assessments/${id}/ai-suggestions`).send({evidenceIds:[filled.evidence[0].id],consent:{acknowledged:true,policyVersion:settings.policyVersion}}).expect(404);expect(provider).not.toHaveBeenCalled();await files.deletePrivate(storageKey);});
test('CA-105 insufficient finding clears stale observed level before exception report',async()=>{const id=await launch(),filled=await fill(id),finding={...filled.items[0],status:'insufficient_evidence',rationale:'No longer enough evidence.'};delete finding.assessedBy;delete finding.assessedAt;const saved=(await call('patch',`/assessments/${id}`).set('If-Match',String(filled.revision)).send({items:[finding]}).expect(200)).body.data;expect(saved.items[0].observedLevelId).toBeUndefined();expect(saved.items[0].rating).toBeUndefined();const pub=(await call('post',`/assessments/${id}/finalise`).set('If-Match',String(saved.revision)).send({classificationId:'development',reason:'Human classification with insufficient evidence.',exceptions:[{criterionId:'criterion-0',reason:'Authorised exception.'}]}).expect(200)).body.data;expect(pub.result.findings[0].observedLevel).toBeNull();expect(pub.result.score.overallScore).toBeNull();});
test('CA-008 direct link launch transaction rejects closed parent and rolls back parent touch on failed creation',async()=>{const appraisal=await Appraisal.create({cycleId:new mongoose.Types.ObjectId(),organizationId:'org-a',employee:{userId:'employee',name:'Employee',email:'employee@example.test'},manager:{userId:'assessor',name:'Assessor',email:'assessor@example.test'},status:'completed'});const input={cycleId:fixture.cycle.id,cycleRevision:fixture.cycle.revision,assignments:[{participantId:'employee',roleVersionId:fixture.role.id,assessorIds:['assessor'],appraisalId:String(appraisal._id)}]};await call('post','/assessments/launch').send(input).expect(409);expect(await Assessment.countDocuments()).toBe(0);await Appraisal.updateOne({_id:appraisal._id},{$set:{status:'not_started'}});const original=Assessment.create.bind(Assessment);jest.spyOn(Assessment,'create').mockImplementation((docs,options)=>options?.session?Promise.reject(new Error('Synthetic linked creation failure')):original(docs,options));await call('post','/assessments/launch').send(input).expect(500);expect(await Assessment.countDocuments()).toBe(0);expect((await Appraisal.findById(appraisal._id)).__v).toBe(appraisal.__v);});
test('CA-104 fresh central authority denial after long AI generation discards draft (separate mocked identity and provider boundaries)',async()=>{const id=await launch(),filled=await fill(id),settings=await require('../services/competency/settingsService').updateSettings(makeCtx(),{aiDraftsEnabled:true,evidenceRetentionDays:30,noticeText:'Synthetic AI processing notice.'},0),evidenceId=filled.evidence[0].id;auth.refreshContext.mockImplementationOnce(async req=>req.competencyContext).mockImplementationOnce(async()=>{throw new(require('../contracts/competency').DomainError)(403,'AUTHORITY_REVOKED','Current Identity authority denied this request.');});const provider=jest.spyOn(require('../services/sharedAIAccountService'),'complete').mockResolvedValue({model:'MOCK Terra model',provider:'MOCK shared account gateway',content:JSON.stringify({observations:[{criterionId:'criterion-0',text:'On-time delivery supported by quoted evidence.',citations:[{evidenceId,spanId:'span-1',quote:'Completed work on schedule.'}]}]})});await call('post',`/assessments/${id}/ai-suggestions`).send({evidenceIds:[evidenceId],consent:{acknowledged:true,policyVersion:settings.policyVersion}}).expect(403);expect(auth.refreshContext).toHaveBeenCalledTimes(2);expect(provider).toHaveBeenCalledTimes(1);expect(await require('../models/CompetencyAISuggestion').countDocuments({status:'ready'})).toBe(0);expect((await require('../models/CompetencyAISuggestion').findOne()).errorCode).toBe('AUTHORITY_REVOKED');});


test('CA-113 capped candidate scan stays incomplete after stale assessor rows are hidden',async()=>{
  const assessmentId=await launch();
  const ctx=makeCtx();
  ctx.organizationWide=false;
  ctx.directory.scope='managed_teams';
  const reports=require('../services/competency/reportService');
  const initial=await reports.cohort(ctx,fixture.cycle.id);
  expect(initial.total).toBe(1);
  expect(initial.truncated).toBe(false);
  const original=await Assessment.findById(assessmentId).lean();
  // Historical assignments match the candidate query, but their participants
  // are absent from today's directory. None may enter visible aggregates.
  const hidden=Array.from({length:2000},(_,index)=>({
    ...original,
    _id:new mongoose.Types.ObjectId(),
    participant:{userId:`stale-cap-${index}`,name:'Hidden stale participant sentinel',departmentId:'hidden-department',teamIds:['hidden-team']},
    definitionSnapshot:{...original.definitionSnapshot,role:{...original.definitionSnapshot.role,name:'Hidden stale role sentinel'}},
    createdAt:new Date(1577836800000+index),
    updatedAt:new Date(1577836800000+index),
  }));
  await Assessment.collection.insertMany(hidden);
  expect(await Assessment.countDocuments({organizationId:'org-a',cycleId:fixture.cycle.id})).toBe(2001);
  const report=await reports.cohort(ctx,fixture.cycle.id);
  expect(report.truncated).toBe(true);
  expect(report.total).toBe(1);
  expect(report.completed).toBe(0);
  expect(report.rows.map(row=>row.participant.userId)).toEqual(['employee']);
  expect(report.completionCounts.not_started).toBe(1);
  expect(report.gaps).toHaveLength(1);
  expect(report.gaps[0].missing).toBe(1);
  expect(report.rankings).toEqual([]);
  expect(report.filters.departmentIds).toEqual(['delivery']);
  expect(report.filters.teamIds).toEqual(['team-a']);
  expect(JSON.stringify(report)).not.toContain('Hidden stale');
  expect(JSON.stringify(report)).not.toContain('hidden-department');
  expect(JSON.stringify(report)).not.toContain('hidden-team');
});
